script:
frappe.ui.form.on('NextHD Ticket', {
    refresh: function(frm) {
        if (!frm.doc.related_problem && !frm.is_new()) {
            frm.add_custom_button('Buat Problem dari Tiket', function() {
                frappe.prompt([
                    {fieldname: 'title', label: 'Judul Problem', fieldtype: 'Data', reqd: 1,
                     default: frm.doc.subject},
                    {fieldname: 'priority', label: 'Prioritas', fieldtype: 'Select',
                     options: 'Kritis\nTinggi\nSedang\nRendah', default: frm.doc.priority}
                ], function(values) {
                    frappe.call({
                        method: 'frappe.client.insert',
                        args: {
                            doc: {
                                doctype: 'NextHD Problem',
                                title: values.title,
                                priority: values.priority,
                                category: frm.doc.category,
                                status: 'Terbuka',
                                related_asset: frm.doc.affected_asset,
                                photos: frm.doc.photos || []
                            }
                        },
                        callback: function(r) {
                            if (r.message) {
                                var problem_name = r.message.name;
                                frappe.call({
                                    method: 'frappe.client.set_value',
                                    args: {
                                        doctype: 'NextHD Ticket',
                                        name: frm.doc.name,
                                        fieldname: 'related_problem',
                                        value: problem_name
                                    },
                                    callback: function() {
                                        frappe.call({
                                            method: 'frappe.client.insert',
                                            args: {
                                                doc: {
                                                    doctype: 'NextHD Problem Ticket',
                                                    parenttype: 'NextHD Problem',
                                                    parent: problem_name,
                                                    parentfield: 'related_tickets',
                                                    ticket: frm.doc.name
                                                }
                                            },
                                            callback: function() {
                                                frappe.msgprint('Problem ' + problem_name + ' berhasil dibuat dan terhubung.');
                                                frm.reload_doc();
                                            }
                                        });
                                    }
                                });
                            }
                        }
                    });
                }, 'Buat Problem Baru dari Tiket Ini');
            });
        }
        if (frm.doc.related_problem) {
            frm.add_custom_button('Lihat Problem: ' + frm.doc.related_problem, function() {
                frappe.set_route('Form', 'NextHD Problem', frm.doc.related_problem);
            });
        }
    }
});

frappe.ui.form.on('NextHD Problem', {
    refresh(frm) {
        if (!frm.is_new() && !frm.doc.known_error) {
            frm.add_custom_button('Buat Known Error dari Problem', function() {
                let d = frappe.new_doc('NextHD Known Error');
                d.title = frm.doc.title;
                d.related_problem = frm.doc.name;
                frappe.set_route('Form', 'NextHD Known Error', d.name);
                frappe.after_ajax(function() {
                    cur_frm.set_value('title', frm.doc.title);
                    cur_frm.set_value('related_problem', frm.doc.name);
                    if (frm.doc.photos && frm.doc.photos.length > 0) {
                        frm.doc.photos.forEach(function(row) {
                            let new_row = frappe.model.add_child(cur_frm.doc, 'NextHD Photo Link', 'photos');
                            new_row.photo = row.photo;
                        });
                    }
                    cur_frm.save().then(() => {
                        let ke_name = cur_frm.doc.name;
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'NextHD Problem',
                                name: frm.doc.name,
                                fieldname: 'known_error',
                                value: ke_name
                            },
                            callback() {
                                frappe.show_alert({message: 'Known Error berhasil dibuat dan ditautkan', indicator: 'green'});
                                frm.reload_doc();
                            }
                        });
                    });
                });
            });
        }
    }
});

frappe.ui.form.on('NextHD Problem', {
    refresh(frm) {
        if (!frm.is_new() && !frm.doc.change_request) {
            frm.add_custom_button('Buat Change Request dari Problem', function() {
                frappe.new_doc('NextHD Change Request', {
                    title: frm.doc.title,
                    related_problem: frm.doc.name
                }, function(new_doc) {
                    new_doc.save().then(() => {
                        let cr_name = new_doc.name;
                        frappe.call({
                            method: 'frappe.client.set_value',
                            args: {
                                doctype: 'NextHD Problem',
                                name: frm.doc.name,
                                fieldname: 'change_request',
                                value: cr_name
                            },
                            callback() {
                                frappe.show_alert({message: 'Change Request berhasil dibuat dan ditautkan', indicator: 'green'});
                                frm.reload_doc();
                                frappe.set_route('Form', 'NextHD Change Request', cr_name);
                            }
                        });
                    });
                });
            });
        }
    }
});

frappe.ui.form.on('NextHD Known Error', {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button('Buat Change Request dari Known Error', function() {
                frappe.new_doc('NextHD Change Request', {
                    title: frm.doc.title,
                    related_problem: frm.doc.related_problem
                }, function(new_doc) {
                    new_doc.save().then(() => {
                        frappe.show_alert({message: 'Change Request berhasil dibuat', indicator: 'green'});
                        frappe.set_route('Form', 'NextHD Change Request', new_doc.name);
                    });
                });
            });
        }
    }
});

frappe.ui.form.on('NextHD Asset', {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button('Buat Change Request dari Asset', function() {
                frappe.new_doc('NextHD Change Request', {
                    title: frm.doc.asset_name,
                    related_asset: frm.doc.name
                }, function(new_doc) {
                    new_doc.save().then(() => {
                        frappe.show_alert({message: 'Change Request berhasil dibuat', indicator: 'green'});
                        frappe.set_route('Form', 'NextHD Change Request', new_doc.name);
                    });
                });
            });
        }
    }
});
